452→	t2 := time.Date(2025, 1, 1, 11, 0, 0, 0, time.UTC)
453→	t3 := time.Date(2025, 1, 1, 12, 0, 0, 0, time.UTC) // newest
454→
455→	cpID1 := createCheckpointOnMetadataBranchFull(t, repo, "session-oldest", id.MustCheckpointID("aaa111bbb222"), t1)
456→	cpID2 := createCheckpointOnMetadataBranchFull(t, repo, "session-middle", id.MustCheckpointID("ccc333ddd444"), t2)
457→	cpID3 := createCheckpointOnMetadataBranchFull(t, repo, "session-newest", id.MustCheckpointID("eee555fff666"), t3)
458→
459→	// Pass checkpoint IDs in reverse chronological order (newest first),
460→	// simulating git CLI squash merge trailer order.
461→	reverseOrderIDs := []id.CheckpointID{cpID3, cpID2, cpID1}
462→	latest, tree, _, err := resolveLatestCheckpoint(context.Background(), reverseOrderIDs)
