468→	if latest.String() != cpID3.String() {
469→		t.Errorf("resolveLatestCheckpoint() = %s, want newest %s", latest, cpID3)
470→	}
471→
472→	// Should return a non-nil tree for reuse
473→	if tree == nil {
474→		t.Error("resolveLatestCheckpoint() returned nil tree")
