476→
477→	// Also verify with chronological order
478→	chronologicalIDs := []id.CheckpointID{cpID1, cpID2, cpID3}
479→	latest2, _, _, err := resolveLatestCheckpoint(context.Background(), chronologicalIDs)
480→	if err != nil {
481→		t.Fatalf("resolveLatestCheckpoint() error = %v", err)
482→	}
483→	if latest2.String() != cpID3.String() {
484→		t.Errorf("resolveLatestCheckpoint() = %s, want newest %s", latest2, cpID3)
